     4	/**
     5	 * The MHPCO price list: the base premium each kind of item is tariffed at.
     6	 *
     7	 * <p>The MHPCO tariffs main items individually and components as a category:
     8	 * every component carries the same base premium, whatever it is made of.
     9	 *
    10	 * <p>Changes whenever the MHPCO revises its tariff or takes on a new kind of
    11	 * item; knows nothing about how a premium is assembled from those amounts.
    12	 */
    13	final class PriceList {
    14	
    15	    private static final int SWORD_BASE_PREMIUM_IN_G = 100;
    16	    private static final int AMULET_BASE_PREMIUM_IN_G = 60;
    17	    private static final int STAFF_BASE_PREMIUM_IN_G = 80;
    18	    private static final int POTION_BASE_PREMIUM_IN_G = 40;
    19	
    20	    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;
    21	
    22	    private static final int NOT_TARIFFED = 0;
    23	
    24	    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS_IN_G = Map.of(
    25	            "sword", SWORD_BASE_PREMIUM_IN_G,
    26	            "amulet", AMULET_BASE_PREMIUM_IN_G,
    27	            "staff", STAFF_BASE_PREMIUM_IN_G,
    28	            "potion", POTION_BASE_PREMIUM_IN_G);
    29	
    30	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    31	
    32	    private PriceList() {
    33	    }
    34	
    35	    static int basePremiumFor(Item item) {
    36	        if (isComponent(item)) {
    37	            return COMPONENT_BASE_PREMIUM_IN_G;
    38	        }
    39	        return MAIN_ITEM_BASE_PREMIUMS_IN_G.getOrDefault(item.type(), NOT_TARIFFED);
    40	    }
    41	
    42	    private static boolean isComponent(Item item) {
    43	        return COMPONENT_TYPES.contains(item.type());
    44	    }
    45	}
